import sqlite3
import json

def parse_hours_open_past_midnight(hours_json):
    """Check if any day in the hours JSON indicates operation past midnight."""
    if not hours_json:
        return False
    try:
        hours_dict = json.loads(hours_json)
    except (json.JSONDecodeError, TypeError):
        return False
    for day_hours in hours_dict.values():
        if not day_hours:
            continue
        # Format like '9:00-2:00' or '9:00-24:00'
        if '-' not in day_hours:
            continue
        _, close_time = day_hours.split('-', 1)
        if ':' not in close_time:
            continue
        hour_part = close_time.split(':')[0]
        try:
            close_hour = int(hour_part)
        except ValueError:
            continue
        if close_hour == 24 or close_hour == 0 or close_hour > 24:
            return True
        # Standard 24-hour format: past midnight means closing hour >= 24 or 0
        # But Yelp often uses 0:xx for midnight+; also sometimes 24:00
        # Also consider cases like '2:00' meaning 2 AM next day
        if close_hour < 6:  # Assume closing before 6 AM counts as past midnight
            return True
    return False

# Database path configuration
sqlite_path = "D:/Yelp-JSON/db/sqlite3/business.db"

try:
    conn = sqlite3.connect(sqlite_path)
    cursor = conn.cursor()

    # Query businesses in Boise with required attributes
    query = '''
    SELECT business_id, name, address, attributes, hours
    FROM business
    WHERE city = ? AND is_open = 1
    '''
    cursor.execute(query, ("Boise",))
    candidates = cursor.fetchall()

    results = []
    for row in candidates:
        business_id, name, address, attributes_json, hours_json = row

        # Parse attributes
        try:
            attributes = json.loads(attributes_json) if attributes_json else {}
        except json.JSONDecodeError:
            attributes = {}

        wifi = attributes.get('WiFi', '').strip('"')
        noise_level = attributes.get('NoiseLevel', '').strip('"')

        # Check WiFi and noise level
        if wifi != 'free':
            continue
        if noise_level not in ['quiet', 'average']:
            continue

        # Check if open past midnight
        if not parse_hours_open_past_midnight(hours_json):
            continue

        results.append({
            'business_id': business_id,
            'name': name,
            'address': address,
            'wifi': wifi,
            'noise_level': noise_level
        })

    # Output results
    if results:
        print(f"Found {len(results)} late-night work-friendly places in Boise:")
        for place in results:
            print(f"- {place['name']} ({place['address']}) | WiFi: {place['wifi']}, Noise: {place['noise_level']}")
    else:
        print("No late-night work-friendly places found in Boise matching the criteria.")

except sqlite3.Error as e:
    print(f"SQLite error: {e}")
except Exception as e:
    print(f"Unexpected error: {e}")
finally:
    if 'conn' in locals():
        conn.close()
